import{_ as p,a0 as s,w as i,s as r,ao as a,I as l,x as e,a1 as n,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"保持自由 - GCC應該接受收費插件嗎？ | LCTT x X-CMD","titleTemplate":false,"description":"保持自由 - GCC應該接受收費插件嗎？ | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"保持自由 - GCC應該接受收費插件嗎？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"保持自由 - GCC應該接受收費插件嗎？ | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140624 Staying free--should GCC allow non-free plug ins","title":"保持自由 - GCC應該接受收費插件嗎？","tag":"201409","desc":""},"relativePath":"201409/20140624 Staying free--should GCC allow non-free plug ins.md","filePath":"[post].md"}'),u={name:"201409/20140624 Staying free--should GCC allow non-free plug ins.md"};function G(f,t,d,L,g,m){const C=s("Link");return i(),r("div",null,[t[14]||(t[14]=a('<h1 id="保持自由-gcc應該接受收費插件嗎" tabindex="-1">保持自由 - GCC應該接受收費插件嗎？ <a class="header-anchor" href="#保持自由-gcc應該接受收費插件嗎" aria-label="Permalink to “保持自由 - GCC應該接受收費插件嗎？”">​</a></h1><blockquote><p>GCC郵件列表中在爭論GCC是否應該接受收費插件，但是認為GCC是一個免費軟件開發的媒介的論調佔得了上風</p></blockquote><p>Gcc以及它在模組化方面的缺失又一次作為一個問題被提出來，並且和市場上的新的編譯器LLVM做了對比。GCC巨大而古老：5百萬行代碼，30年研發時間，並且還在繼續增長。相比較而言，LLVM更加年輕，更加模組化，並且允許所有的語言都作為一個模組添加進去。</p><p>LLVM的核心是‘開放源代碼’。GCC是反著作權（copyleft）代表，是嚴格的免費軟件，她不允許以任何形式收費的插件的代碼進入到GCC的代碼中。爭論的一種意見，正如Eric Raymond説的，“FSF不可能既阻止持有所有權的供應者添加他們的插件到一個免費編譯器中，又讓這個編譯器得到發展。就像馬兒已經偏離了跑道，反對插件策略的戰略目標已經徹底的失敗了”。</p><p>LLVM已經被蘋果公司採用作為OS X和蘋果硬件上GCC的替代品，並且正在變得流行起來，特別是在BSD系列操作系統的用户中間。LLVM的擁護者推測LLVM將會在更廣闊的應用程序和移動設備開發市場上成為GCC的替代者。GCC的反對者們的觀點是GCC太過複雜，並且開發者們必須遵守她的‘反著作權（copyleft）’。這限制了那些不想在‘反著作權（copyleft）’許可證下發布他們的語言或者軟件產品。作為典型，蘋果公司有一個很長的厭惡免費軟件的歷史。他們也不允許遵守‘反著作權（copyleft）’的軟件通過他們的App Store發佈。</p><p>LLVM和GCC之間的爭論其實是GNU/Linux和BSD系列、開放源代碼和免費軟件之間歷史差異的翻新版。開放源碼的開發者允許代碼被以任何形式的使用，免費或者維持版權。免費軟件則嚴格地規定，代碼或者針對代碼做的更新，必須保持永久免費。免費軟件的支持者認為完整的‘反著作權’授權有助於GCC的發展，並且已經將Linux和免費軟件帶到一個其他方式無法到達的高度，同時保證了免費軟件不會被收購或者墮落成商業利益。開放源碼的支持者則認為開放源碼更加的自由，因為使用這沒有受到限制，他們可以隨意使用，包括開發非開源的版本。</p><p>GNU編譯器集合（GCC）一直是免費軟件發展的關鍵。編譯器是稀有且昂貴的商品，版權軟件公司也充斥着對不符合標準的特性的需求。讓軟件兼容不同的機器和操作系統是一個非必需的複雜任務。GCC作為第一個真正免費的跨平台編譯器，簡化了這個過程。</p><p>GCC對於軟件開發者和移動設備開發者來説也是一個劃時代的產品，而不僅僅對於那些免費軟件概念提出者。GCC不但免費和可移植，她跨越不同硬件架構的普遍性和公用性使得更加容易做到軟件的兼容性、魯棒性和一致性。這和John Gilmore，Michael Tiemann和David Henkel-Wallace在開發GCC時發現的一樣。這也是Cygnus Solutions公司主要的賣點，Cygnus Solutions是第一家靠賣免費軟件賺錢的公司。[譯註：Cygnus Solutions是John Gilmore, Michael Tiemann and David Henkel- Wallace創辦的公司，同時也是GNU幾個主要產品的貢獻者]</p><p>LLVM和GCC之間主要的技術差異集中在組成‘前端’，‘中端’，‘後端’的模組分割。‘前端’用來翻譯特定的語言。‘中端’對翻譯後產生的代碼進行優化。‘後端’將優化後的代碼轉化成特定硬件架構的機器碼。LLVM將這些模組分割成不同的實體，但是由於語義的和歷史的原因，GCC模糊了這些模組之間的界限。</p><p>對於一個免費軟件項目，添加一種新的語言或者架構到GCC也許是一個非常困難的過程，添加有版權的插件也是不允許的。由於模組間界限非常不明確，最容易的添加方法就是讓添加的特性遵循免費軟件許可證。最初的開發者也許想保持代碼的封閉和版權，但最後不得不將代碼以免費軟件發佈。早期的C++以及Objective C就被認為是其中典型的例子。</p><p>與此相反，LLVM允許，甚至也許可以説是鼓勵添加和發展版權語言和架構，比如英偉達基於Clang和LLVM的對於GPU開發的NVCC。NVCC的源代碼是免費軟件或者開源軟件開發者獲取不到的。</p>',11)),l("p",null,[t[1]||(t[1]=e("Richard Stallman",-1)),n(C,{href:"http://lwn.net/articles/582241"},{default:o(()=>[...t[0]||(t[0]=[e("對這方面的演講中",-1)])]),_:1}),t[2]||(t[2]=e("旗幟鮮明地宣佈：“在免費軟件運動中，我們為自由而戰。免費軟件的的價值觀從根本上就和開源軟件不同，後者以寫‘更好的代碼’為終極目標。如果GCC從免費的編譯器變成非免費的編譯器，她將不再能夠達成自由的目標。",-1))]),t[15]||(t[15]=l("p",null,"“Clang和LLVM的開發者不認可我們的價值觀和目標，所以得出了跟我們不一樣的結論。他們反對我們採取的捍衞自由的措施，因為他們只看到這對他們造成的不便，卻沒有看到（或者不關心）他們真正的需求。我猜測他們把他們的工作定義為‘開源’，並且漠視自由。”",-1)),t[16]||(t[16]=l("p",null,"GCC開發者們不可能在許可證的條件上妥協。LLVM在某些行業的部門非常流行，因為它很年輕很新，在編程語言的浪潮中跳躍式發展着。流行的風向着更加開放奔跑，GCC決心跟商業利益死磕也許是這個長期演進路上的一大助力。Unix公司們從80和90年代的Unix戰爭中學到了一些東西。語言和操作系統都是工具，它們最好是開放和共享的。GCC是免費軟件，不屬於任何人。",-1)),t[17]||(t[17]=l("hr",null,null,-1)),l("p",null,[t[4]||(t[4]=e("via: ",-1)),n(C,{href:"http://www.linuxuser.co.uk/features/staying-free-should-gcc-allow-non-free-plug-ins"},{default:o(()=>[...t[3]||(t[3]=[e("http://www.linuxuser.co.uk/features/staying-free-should-gcc-allow-non-free-plug-ins",-1)])]),_:1})]),l("p",null,[t[7]||(t[7]=e("譯者：",-1)),n(C,{href:"https://github.com/CNprober"},{default:o(()=>[...t[5]||(t[5]=[e("love_daisy_love",-1)])]),_:1}),t[8]||(t[8]=e(" 校對：",-1)),n(C,{href:"https://github.com/wxy"},{default:o(()=>[...t[6]||(t[6]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[11]||(t[11]=e("本文由 ",-1)),n(C,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[9]||(t[9]=[e("LCTT",-1)])]),_:1}),t[12]||(t[12]=e(" 原創翻譯，",-1)),n(C,{href:"http://linux.cn/"},{default:o(()=>[...t[10]||(t[10]=[e("Linux中國",-1)])]),_:1}),t[13]||(t[13]=e(" 榮譽推出",-1))])])}const M=p(u,[["render",G]]);export{x as __pageData,M as default};
